node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

const newId = crypto.randomUUID();
const existingReminder = db.prepare(\"SELECT * FROM ts_reminders WHERE reminder_id = 'c6a3f80e-185e-49ee-83c8-6d8947920fcd'\").get();

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`).run(
  newId,
  existingReminder.content,
  existingReminder.creation_timestamp,
  existingReminder.reminder_timestamp,
  37.7749,
  -122.4194,
  existingReminder.created_at
);

// Verify
const newReminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(newId);
console.log('New reminder created:');
console.log(JSON.stringify(newReminder, null, 2));
"
